```razor
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome! Browse our departments and courses, or submit an enrollment request.</p>

<div class="row mb-4">
    <div class="col-md-8">
        <form method="get" action="courses" data-enhance>
            <div class="input-group">
                <input type="text" name="search" class="form-control" placeholder="Search courses by title, ID, or instructor..." />
                <button type="submit" class="btn btn-primary">Search</button>
            </div>
        </form>
    </div>
</div>

<h2>Departments</h2>
<div class="row mb-4">
    @foreach (var dept in departments)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                    <a href="courses?department=@dept.Id" class="btn btn-outline-primary btn-sm" data-enhance-nav>View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Featured Courses</h2>
<div class="row">
    @foreach (var course in featuredCourses)
    {
        <div class="col-md-6 mb-3">
            <div class="card h-100 border-primary">
                <div class="card-body">
                    <h5 class="card-title">@course.Id — @course.Title</h5>
                    <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                    <a href="courses/@course.Id" class="btn btn-primary btn-sm" data-enhance-nav>View Details</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Department> departments = [];
    private List<Course> featuredCourses = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}
```

### 9. Create Courses.razor

Create `/tmp/sv-d136b914a1604636a84dac7c70f729b4/UniversityCourseCatalog/Components/Pages/Courses.razor`:

```razor
@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row mb-4 g-2" data-enhance>
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, ID, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (!string.IsNullOrWhiteSpace(Search) || !string.IsNullOrWhiteSpace(Department))
{
    <p class="text-muted mb-3">
        Showing @courses.Count result(s)
        @if (!string.IsNullOrWhiteSpace(Search)) { <text> for "<strong>@Search</strong>"</text> }
        @if (!string.IsNullOrWhiteSpace(Department) && currentDepartment is not null) { <text> in <strong>@currentDepartment.Name</strong></text> }
        — <a href="courses" data-enhance-nav>Clear filters</a>
    </p>
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your criteria. Try adjusting your search or filter.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Course ID</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Id</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary" data-enhance-nav>Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private List<Department> departments = [];
    private List<Course> courses = [];
    private Department? currentDepartment;

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Department, Search);
        if (!string.IsNullOrWhiteSpace(Department))
        {
            currentDepartment = Catalog.GetDepartment(Department);
        }
    }
}
```

