{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must contain only letters and numbers.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Exploration of numbers, structures, and mathematical reasoning." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Examination of past events and their impact on the modern world." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, and object-oriented design. No prior experience required.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and CS education.", IsFeatured = true },
        new() { Id = "CS201", Title = "Data Structures & Algorithms", Description = "An in-depth study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming). Prerequisites: CS101.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Instructor = "Dr. Alan Turing", InstructorBio = "Dr. Turing is an expert in theoretical computer science and algorithm design with over 20 publications in top-tier conferences.", IsFeatured = false },
        new() { Id = "CS301", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and an introduction to NoSQL databases. Includes a semester-long project building a full-stack application.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3, Schedule = "Mon/Wed 1:00–2:15 PM", Instructor = "Prof. Grace Hopper", InstructorBio = "Prof. Hopper has industry experience at leading tech companies and specializes in database architecture and distributed systems.", IsFeatured = true },
        new() { Id = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning mathematician whose work spans abstract algebra and theoretical physics.", IsFeatured = true },
        new() { Id = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications. Essential for computer science, physics, and engineering students.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Instructor = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss has been teaching mathematics for 12 years and is known for his engaging lecture style and real-world applications.", IsFeatured = false },
        new() { Id = "ENG101", Title = "Composition & Rhetoric", Description = "Develop effective writing skills through essay composition, argumentation, and critical analysis of texts.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Instructor = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is a published author and literary critic with expertise in modern literature and creative nonfiction.", IsFeatured = false },
        new() { Id = "ENG201", Title = "American Literature", Description = "A survey of American literature from the colonial period to the present, examining major authors, movements, and themes.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", Instructor = "Dr. Mark Twain", InstructorBio = "Dr. Twain specializes in 19th-century American literature and humor studies. He has authored two books on satirical writing.", IsFeatured = false },
        new() { Id = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics for science and engineering majors.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Instructor = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a renowned physicist whose research in nuclear physics has earned international recognition.", IsFeatured = true },
        new() { Id = "PHYS201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Prerequisites: PHYS101 and MATH101.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", Instructor = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is celebrated for his innovative teaching methods and contributions to quantum electrodynamics.", IsFeatured = false },
        new() { Id = "HIST101", Title = "World History to 1500", Description = "A global survey of major civilizations, empires, and cultural developments from prehistory to the early modern period.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Instructor = "Dr. Herodotus Smith", InstructorBio = "Dr. Smith is a historian specializing in ancient civilizations with extensive fieldwork experience in the Mediterranean region.", IsFeatured = false },
        new() { Id = "HIST201", Title = "Modern World History", Description = "Examines global developments from 1500 to the present, including colonialism, industrialization, world wars, and globalization.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", Instructor = "Prof. Eleanor Roosevelt", InstructorBio = "Prof. Roosevelt focuses on 20th-century diplomatic history and human rights movements.", IsFeatured = false },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? departmentId = null, string? search = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(search, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database.
        return GetCourse(request.CourseId) is not null;
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row mb-4 g-2" data-enhance>
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, ID, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (!string.IsNullOrWhiteSpace(Search) || !string.IsNullOrWhiteSpace(Department))
{
    <p class="text-muted mb-3">
        Showing @courses.Count result(s)
        @if (!string.IsNullOrWhiteSpace(Search)) { <text> for "<strong>@Search</strong>"</text> }
        @if (!string.IsNullOrWhiteSpace(Department) && currentDepartment is not null) { <text> in <strong>@currentDepartment.Name</strong></text> }
        — <a href="courses" data-enhance-nav>Clear filters</a>
    </p>
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your criteria. Try adjusting your search or filter.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Course ID</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Id</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary" data-enhance-nav>Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private List<Department> departments = [];
    private List<Course> courses = [];
    private Department? currentDepartment;

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Department, Search);
        if (!string.IsNullOrWhiteSpace(Department))
        {
            currentDepartment = Catalog.GetDepartment(Department);
        }
    }
}

@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The course "<strong>@CourseId</strong>" could not be found.</p>
    <a href="courses" class="btn btn-primary" data-enhance-nav>Back to Courses</a>
}
else
{
    <PageTitle>@course.Id — @course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="" data-enhance-nav>Home</a></li>
            <li class="breadcrumb-item"><a href="courses?department=@course.DepartmentId" data-enhance-nav>@course.DepartmentName</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Id</li>
        </ol>
    </nav>

    <h1>@course.Id — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@course.Description</p>

            <h2>Schedule</h2>
            <p><span class="badge bg-secondary">@course.Schedule</span></p>

            <h2>Credits</h2>
            <p><span class="badge bg-primary fs-6">@course.Credits credits</span></p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6>@course.Instructor</h6>
                    <p class="card-text">@course.InstructorBio</p>
                </div>
            </div>
            <div class="mt-3">
                <a href="enroll?course=@course.Id" class="btn btn-success w-100" data-enhance-nav>Enroll in This Course</a>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <a href="courses" class="btn btn-outline-secondary" data-enhance-nav>← Back to Courses</a>
    </div>
}

@code {
    [Parameter] public string CourseId { get; set; } = string.Empty;

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(CourseId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong> (ID: @Model.StudentId). Your enrollment request for <strong>@submittedCourseName</strong> has been received.</p>
        <a href="enroll" class="btn btn-outline-success" data-enhance-nav>Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <AntiforgeryToken />
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="">— Select a Course —</option>
                        @foreach (var course in allCourses)
                        {
                            <option value="@course.Id">@course.Id — @course.Title (@course.DepartmentName)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public string? Course { get; set; }

    private List<Course> allCourses = [];
    private bool submitted;
    private string submittedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetCourses();
        if (!string.IsNullOrWhiteSpace(Course) && string.IsNullOrWhiteSpace(Model.CourseId))
        {
            Model.CourseId = Course;
        }
    }

    private void HandleSubmit()
    {
        if (Catalog.SubmitEnrollment(Model))
        {
            var course = Catalog.GetCourse(Model.CourseId);
            submittedCourseName = course is not null ? $"{course.Id} — {course.Title}" : Model.CourseId;
            submitted = true;
        }
    }
}

