    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                    <a href="courses?department=@dept.Id" class="btn btn-outline-primary btn-sm" data-enhance-nav>View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Featured Courses</h2>
<div class="row">
    @foreach (var course in featuredCourses)
    {
        <div class="col-md-6 mb-3">
            <div class="card h-100 border-primary">
                <div class="card-body">
                    <h5 class="card-title">@course.Id — @course.Title</h5>
                    <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                    <a href="courses/@course.Id" class="btn btn-primary btn-sm" data-enhance-nav>View Details</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Department> departments = [];
    private List<Course> featuredCourses = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

