@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong> (ID: @Model.StudentId). Your enrollment request for <strong>@submittedCourseName</strong> has been received.</p>
        <a href="enroll" class="btn btn-outline-success" data-enhance-nav>Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <AntiforgeryToken />
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="">— Select a Course —</option>
                        @foreach (var course in allCourses)
                        {
                            <option value="@course.Id">@course.Id — @course.Title (@course.DepartmentName)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public string? Course { get; set; }

    private List<Course> allCourses = [];
    private bool submitted;
    private string submittedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetCourses();
        if (!string.IsNullOrWhiteSpace(Course) && string.IsNullOrWhiteSpace(Model.CourseId))
        {
            Model.CourseId = Course;
        }
    }

    private void HandleSubmit()
    {
        if (Catalog.SubmitEnrollment(Model))
        {
            var course = Catalog.GetCourse(Model.CourseId);
            submittedCourseName = course is not null ? $"{course.Id} — {course.Title}" : Model.CourseId;
            submitted = true;
        }
    }
}

